local metadata={id="mythicPlus",name="MythicPlus",displayName=L["DISPLAY_NAME"],description=L["DESCRIPTION"],version=addonVersion,moduleType="feature",category="feature",permissions={{id="mythicplus-read",category="Mythic+",defaults={member=true}},"sync-send","sync-receive"},dependencies={"core"},capabilities={"character.scan.mythicplus"},ui={},options={},administration={},data={block="mythicPlus",snapshotType="mythicplus",schemaVersion=3,capability="character.scan.mythicplus"},sync={domains={"character"}},enabledByDefault=true,ruleFields={{id="mythicplus.rating",aliases={"mythicScore"},type="number",name=L["RULE_FIELD_RATING"],nameKey="RULE_FIELD_RATING",description=L["RULE_FIELD_RATING_DESC"],descriptionKey="RULE_FIELD_RATING_DESC",category=L["DISPLAY_NAME"],dependencies={"mythicPlus"},unit="rating",resolver=function(context)local block=context.character and context.character.mythicPlus or HolyStorm.Data.CharacterStore:GetBlock(context.characterUUID,"mythicPlus");return block and tonumber(block.overallScore)or nil end}}}
local function plain(v,depth) if type(v)~="table"then return (type(v)=="string"or type(v)=="number"or type(v)=="boolean")and v or nil end;if depth>5 then return nil end;local r={};for k,x in pairs(v)do if type(k)=="string"or type(k)=="number"then r[k]=plain(x,depth+1)end end;return r end
local function affixNameKey(value)return type(value)=="string"and value:lower():gsub("|c%x%x%x%x%x%x%x%x",""):gsub("|r",""):gsub("[%s%p%c]+","")or nil end
local function snapshotAffixScores(scores)local result=plain(scores,0);if type(result)~="table"then return result end;local categories={[affixNameKey(L["TYRANNICAL"]) ]="TYRANNICAL",[affixNameKey(L["FORTIFIED"]) ]="FORTIFIED"};for _,entry in pairs(result)do if type(entry)=="table"then entry.category=categories[affixNameKey(entry.name)]end end;return result end
local function bestRun(intime,overtime,affixScores)
 local best;local function consider(entry,overTime)local score=entry and tonumber(entry.dungeonScore or entry.score or entry.seasonScore);local level=entry and tonumber(entry.level or entry.bestLevel);if level and level>0 and(not best or(score or 0)>(best.score or 0)or((score or 0)==(best.score or 0)and level>(best.level or 0)))then best={level=level,score=score or 0,durationSec=tonumber(entry.durationSec),overTime=overTime==true or entry.overTime==true}end end
 consider(intime,false);consider(overtime,true);for _,entry in pairs(type(affixScores)=="table"and affixScores or{})do consider(entry,entry.overTime)end;return best
