  local hasDungeonScore=false;for _,id in ipairs(cm.GetMapTable and cm.GetMapTable()or{})do local name,instanceId,timeLimit,texture,background,mapId=cm.GetMapUIInfo(id);local intime,overtime;if mp.GetSeasonBestForMap then intime,overtime=mp.GetSeasonBestForMap(id)end;local scores,overall;if mp.GetSeasonBestAffixScoreInfoForMap then scores,overall=mp.GetSeasonBestAffixScoreInfoForMap(id)end;local best=bestRun(intime,overtime,scores);local score=tonumber(overall)or(best and best.score)or 0;if score>0 or(best and best.level and best.level>0)then hasDungeonScore=true end;s.dungeons[#s.dungeons+1]={challengeMapId=id,name=name,instanceId=instanceId,mapId=mapId,timeLimit=timeLimit,texture=texture,background=background,bestInTime=plain(intime,0),bestOverTime=plain(overtime,0),affixScores=snapshotAffixScores(scores),bestRun=plain(best,0),score=score}end
